class Solution {
public:
    int minimumSemesters(int n, vector<vector<int>>& relations) {
        vector<vector<int>> graph(n + 1);
        vector<int> indegree(n + 1, 0);
        for (const auto& edge : relations) {
            graph[edge[0]].push_back(edge[1]);
            ++indegree[edge[1]];
        }
        queue<int> q;
        for (int i = 1; i <= n; ++i) {
            if (indegree[i] == 0) {
                q.push(i);
            }
        }
        int taken = 0;
        int semesters = 0;
        while (!q.empty()) {
            int count = q.size();
            ++semesters;
            while (count-- > 0) {
                int course = q.front();
                q.pop();
                ++taken;
                for (int next : graph[course]) {
                    if (--indegree[next] == 0) {
                        q.push(next);
                    }
                }
            }
        }
        return taken == n ? semesters : -1;
    }
};
